/**
 * Client for fetching live foreign-exchange rates from the provider bound to
 * the Named Credential FB_Exchange_Rates.
 */
public class ExchangeRateClient {
    /** Exception thrown for validation failures, callout failures or parse errors. */
    public class ExchangeRateException extends Exception {}

    /**
     * Returns the live rate for each requested quote currency against the given
     * base currency.
     *
     * @param baseCurrency    Three-letter base currency code (case-insensitive).
     * @param quoteCurrencies Set of three-letter quote currency codes.
     * @return Map of normalised quote code to rate.
     */
    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        // --- Validate inputs before making any callout ---
        if (baseCurrency == null) {
            throw new ExchangeRateException('Base currency is required');
        }
        String base = baseCurrency.trim().toUpperCase();
        if (!base.matches('[A-Z]{3}')) {
            throw new ExchangeRateException('Base currency must be a three-letter code: ' + baseCurrency);
        }
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('At least one quote currency is required');
        }
        Set<String> quotes = new Set<String>();
        for (String quote : quoteCurrencies) {
            if (quote == null) {
                throw new ExchangeRateException('Quote currency cannot be null');
            }
            String code = quote.trim().toUpperCase();
            if (!code.matches('[A-Z]{3}')) {
                throw new ExchangeRateException('Quote currency must be a three-letter code: ' + quote);
            }
            quotes.add(code);
        }

        // --- Build the Named Credential callout ---
        String symbols = String.join(quotes, ',');
        String endpoint = 'callout:FB_Exchange_Rates/v1/latest?base=' + base + '&symbols=' + symbols;

        HttpRequest req = new HttpRequest();
        req.setEndpoint(endpoint);
        req.setMethod('GET');
        req.setHeader('Accept', 'application/json');

        // --- Execute with a single retry on 503 ---
        Http http = new Http();
        HttpResponse response = http.send(req);
        Integer status = response.getStatusCode();
        if (status == 503) {
            response = http.send(req);
            status = response.getStatusCode();
        }
        if (status != 200) {
            throw new ExchangeRateException('Exchange rate service returned HTTP status ' + status);
        }

        // --- Parse the response ---
        String body = response.getBody();
        if (String.isBlank(body)) {
            throw new ExchangeRateException('Empty response body from exchange rate service');
        }
        Map<String, Object> parsed;
        try {
            parsed = (Map<String, Object>) JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new ExchangeRateException('Cannot parse exchange rate response body');
        }
        if (parsed == null || !(parsed.get('rates') instanceof Map)) {
            throw new ExchangeRateException('No rates object in exchange rate response');
        }
        Map<String, Object> rates = (Map<String, Object>) parsed.get('rates');

        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String code : quotes) {
            Object rateValue = rates.get(code);
            if (rateValue == null) {
                throw new ExchangeRateException('No exchange rate for currency: ' + code);
            }
            if (!(rateValue instanceof Double)) {
                throw new ExchangeRateException('Invalid exchange rate for currency: ' + code);
            }
            result.put(code, Decimal.valueOf((Double) rateValue));
        }
        return result;
    }
}
