public class ContactDomainService {

    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new Map<String, List<Contact>>();
        }

        Map<String, List<Contact>> domainToContacts = new Map<String, List<Contact>>();

        for (Contact contact : [SELECT Id, Email, AccountId FROM Contact WHERE AccountId IN :accountIds]) {
            if (String.isBlank(contact.Email)) {
                continue;
            }

            Integer atIndex = contact.Email.indexOf('@');
            if (atIndex < 0) {
                continue;
            }

            String domain = contact.Email.substring(atIndex + 1).toLowerCase();

            List<Contact> contactsForDomain = domainToContacts.get(domain);
            if (contactsForDomain == null) {
                contactsForDomain = new List<Contact>();
                domainToContacts.put(domain, contactsForDomain);
            }
            contactsForDomain.add(contact);
        }

        return domainToContacts;
    }
}
