public with sharing class ContactLookupAction {

    /**
     * Finds the Contact that matches each email address.
     * - Emails are matched case-insensitively and trimmed before lookup.
     * - A blank/null email, or an email with no matching Contact, yields found = false.
     * - When several Contacts share an email, the earliest CreatedDate wins.
     * - Exactly one Result is returned per Request, in the same order.
     * - A single SOQL query serves the whole batch (up to 200 requests).
     */
    @InvocableMethod(
        label = 'Find Contact by Email',
        description = 'Returns the Contact (by Id) matching each email, or not found when no match exists.'
    )
    public static List<Result> find(List<Request> requests) {
        // Normalise every request and remember which ones carry a usable email.
        Map<Integer, String> emailByRequestIndex = new Map<Integer, String>();
        Set<String> emailsToQuery = new Set<String>();

        for (Integer i = 0; i < requests.size(); i++) {
            String raw = requests[i].email;
            String normalized = (raw == null) ? null : raw.trim();
            if (normalized != null && !normalized.isEmpty()) {
                emailByRequestIndex.put(i, normalized);
                emailsToQuery.add(normalized.toLowerCase());
            }
        }

        // Lower-cased email -> Id of the earliest-created Contact.
        Map<String, Id> emailToContactId = new Map<String, Id>();

        if (!emailsToQuery.isEmpty()) {
            for (Contact c : [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :emailsToQuery
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                String key = (c.Email == null) ? null : c.Email.trim().toLowerCase();
                if (key != null && !emailToContactId.containsKey(key)) {
                    // First hit per key is the earliest CreatedDate because of the ORDER BY.
                    emailToContactId.put(key, c.Id);
                }
            }
        }

        List<Result> results = new List<Result>();
        results.reserve(requests.size());

        for (Integer i = 0; i < requests.size(); i++) {
            Result r = new Result();
            String normalized = emailByRequestIndex.get(i);
            if (normalized != null) {
                Id contactId = emailToContactId.get(normalized.toLowerCase());
                if (contactId != null) {
                    r.contactId = contactId;
                    r.found = true;
                } else {
                    r.found = false;
                }
            } else {
                r.found = false;
            }
            results.add(r);
        }

        return results;
    }

    public class Request {
        @InvocableVariable(required = true)
        public String email;
    }

    public class Result {
        @InvocableVariable
        public Id contactId;

        @InvocableVariable
        public Boolean found;
    }
}
