public with sharing class LeadImportService {

    public static ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();
        result.successCount = 0;
        result.insertedIds = new List<Id>();
        result.errorsByIndex = new Map<Integer, String>();

        if (leads == null || leads.isEmpty()) {
            return result;
        }

        List<Lead> toInsert = new List<Lead>();
        List<Integer> originalIndices = new List<Integer>();
        Set<String> seenEmails = new Set<String>();

        // Identify duplicates and build the insert list, preserving original input order.
        for (Integer i = 0; i < leads.size(); i++) {
            Lead lead = leads[i];
            String email = lead.Email;
            boolean isDuplicate = false;

            if (email != null) {
                String trimmed = email.trim();
                if (trimmed != '') {
                    String normalized = trimmed.toLowerCase();
                    if (seenEmails.contains(normalized)) {
                        isDuplicate = true;
                        result.errorsByIndex.put(i, 'Duplicate email in import: ' + normalized);
                    } else {
                        seenEmails.add(normalized);
                    }
                }
            }

            if (!isDuplicate) {
                toInsert.add(lead);
                originalIndices.add(i);
            }
        }

        // Apply default LeadSource before any DML.
        for (Lead l : toInsert) {
            if (l.LeadSource == null || l.LeadSource.trim() == '') {
                l.LeadSource = 'Web';
            }
        }

        // Single DML statement; allOrNothing=false so one failure does not roll back others.
        Map<Integer, Database.SaveResult> resultsByIndex = new Map<Integer, Database.SaveResult>();
        if (!toInsert.isEmpty()) {
            List<Database.SaveResult> saveResults = Database.insert(toInsert, false);
            for (Integer j = 0; j < saveResults.size(); j++) {
                resultsByIndex.put(originalIndices.get(j), saveResults[j]);
            }
        }

        // Assemble the result in original input order.
        for (Integer i = 0; i < leads.size(); i++) {
            if (resultsByIndex.containsKey(i)) {
                Database.SaveResult sr = resultsByIndex.get(i);
                if (sr.isSuccess()) {
                    result.successCount++;
                    result.insertedIds.add(sr.getId());
                } else {
                    List<String> messages = new List<String>();
                    for (Database.Error err : sr.getErrors()) {
                        messages.add(err.getMessage());
                    }
                    result.errorsByIndex.put(i, String.join(messages, '; '));
                }
            }
            // Duplicate leads already have an error entry and are not inserted.
        }

        return result;
    }

    public class ImportResult {
        public Integer successCount;
        public List<Id> insertedIds;
        public Map<Integer, String> errorsByIndex;
    }
}
