public with sharing class ShipmentEventPublisher {

    public static class Shipment {
        public String orderNumber;
        public String trackingNumber;
        public String carrier;

        public Shipment(String orderNumber, String trackingNumber, String carrier) {
            this.orderNumber = orderNumber;
            this.trackingNumber = trackingNumber;
            this.carrier = carrier;
        }
    }

    public static Integer publishShipments(List<Shipment> shipments) {
        if (shipments == null || shipments.isEmpty()) {
            return 0;
        }

        List<Event> eventsToPublish = new List<Event>();
        for (Shipment shipment : shipments) {
            if (shipment == null || String.isBlank(shipment.orderNumber)) {
                continue;
            }

            FB_Shipment_Event__e event = new FB_Shipment_Event__e();
            event.Order_Number__c = shipment.orderNumber;
            event.Tracking_Number__c = shipment.trackingNumber;
            event.Carrier__c = shipment.carrier;
            eventsToPublish.add(event);
        }

        if (eventsToPublish.isEmpty()) {
            return 0;
        }

        List<Event> published = EventBus.publish(eventsToPublish);
        return published == null ? eventsToPublish.size() : published.size();
    }
