public class ErpAccountSyncJob implements Queueable {
    private Set<Id> accountIds;
    private Integer attempt;

    public ErpAccountSyncJob(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds;
        this.attempt = attempt;
    }

    public void execute(QueueableContext context) {
        // Attach the finalizer before any work so it runs regardless of success or failure.
        System.addFinalizer(new ErpSyncFinalizer(accountIds, attempt));

        // Set Description on every account and save all-or-nothing.
        // If any record cannot be saved the update throws and the transaction rolls back.
        List<Account> accounts = new List<Account>();
        for (Id id : accountIds) {
            accounts.add(new Account(Id = id));
        }
        for (Account a : accounts) {
            a.Description = 'Synced to ERP';
        }
        update accounts;
    }
}
