public with sharing class OpportunityRollupService {

    /**
     * Returns the total won Amount for each requested account for the current
     * calendar year.
     *
     * The aggregate is computed in the database with a single aggregate SOQL
     * query (SUM with GROUP BY), so individual opportunity records are never
     * loaded. The running user's sharing is respected because the class is
     * declared with sharing.
     *
     * @param accountIds the accounts to roll up
     * @return a map of account Id to total won Amount this year. Every requested
     *         account Id is a key; accounts with no qualifying opportunities, or
     *         whose qualifying opportunities all have a blank Amount, map to 0
     *         (never null). A null or empty set returns an empty map.
     */
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new Map<Id, Decimal>();
        }

        // Current calendar year, evaluated in the running user's timezone.
        Integer year = Date.today().year();
        Date yearStart = Date.newDate(year, 1, 1);
        Date yearEnd = Date.newDate(year, 12, 31);

        // Single aggregate query: one SUM per account, filtered to won
        // opportunities closing in the current year.
        Map<Id, Decimal> aggregates = new Map<Id, Decimal>();
        for (AggregateResult ar : [
            SELECT AccountId,
                   SUM(Amount) totalAmount
            FROM Opportunity
            WHERE IsWon = true
              AND CloseDate >= :yearStart
              AND CloseDate <= :yearEnd
              AND AccountId IN :accountIds
            GROUP BY AccountId
        ]) {
            aggregates.put((Id) ar.get('AccountId'), (Decimal) ar.get('totalAmount'));
        }

        // Ensure every requested account is a key; missing aggregates (no
        // qualifying rows, or all blank Amounts -> SUM returns null) become 0.
        Map<Id, Decimal> result = new Map<Id, Decimal>();
        for (Id accountId : accountIds) {
            Decimal amount = aggregates.get(accountId);
            result.put(accountId, amount == null ? Decimal.ZERO : amount);
        }
        return result;
    }
}
