    public override void onAfterInsert() {
        Set<Id> wonIds = new Set<Id>();
        for (Id id : Trigger.newMap.keySet()) {
            Opportunity opp = (Opportunity) Trigger.newMap.get(id);
            if (opp.StageName == 'Closed Won') {
                wonIds.add(id);
            }
        }
        if (!wonIds.isEmpty()) {
            IOpportunityFulfilmentService service = Application.Service.newInstance(IOpportunityFulfilmentService.class);
            service.startFulfilment(wonIds);
        }
    }

    public override void onAfterUpdate() {
        Set<Id> wonIds = new Set<Id>();
        for (Id id : Trigger.newMap.keySet()) {
            Opportunity newOpp = (Opportunity) Trigger.newMap.get(id);
            Opportunity oldOpp = (Opportunity) Trigger.oldMap.get(id);
            if (oldOpp != null && oldOpp.StageName != 'Closed Won' && newOpp.StageName == 'Closed Won') {
                wonIds.add(id);
            }
        }
        if (!wonIds.isEmpty()) {
            IOpportunityFulfilmentService service = Application.Service.newInstance(IOpportunityFulfilmentService.class);
            service.startFulfilment(wonIds);
        }
    }
}
