            return new Opportunities(record);
        }
    }

    public override void beforeInsert(fflib_SObjectDomain.Records records) {
        validateAmountNotNegative(records);
    }

    public override void beforeUpdate(fflib_SObjectDomain.Records records, fflib_SObjectDomain.Records oldRecords) {
        validateAmountNotNegative(records);

        if (oldRecords == null) {
            return;
        }

        Map<Id, fflib_SObjectDomain.Record> oldById = new Map<Id, fflib_SObjectDomain.Record>();
        for (fflib_SObjectDomain.Record oldRecord : oldRecords) {
            oldById.put((Id) oldRecord.get('Id'), oldRecord);
        }

        for (fflib_SObjectDomain.Record record : records) {
            fflib_SObjectDomain.Record oldRecord = oldById.get((Id) record.get('Id'));
            if (oldRecord == null) {
                continue;
            }

            if ('Closed Won'.equals((String) oldRecord.get('StageName'))) {
                Decimal oldAmount = (Decimal) oldRecord.get('Amount');
                Decimal newAmount = (Decimal) record.get('Amount');
                if (amountChanged(oldAmount, newAmount)) {
                    fflib_SObjectDomain.error('Amount cannot change on a won opportunity.', record, 'Amount');
                }
            }
        }
    }

    private void validateAmountNotNegative(fflib_SObjectDomain.Records records) {
        for (fflib_SObjectDomain.Record record : records) {
            Decimal amount = (Decimal) record.get('Amount');
            if (amount != null && amount < 0) {
                fflib_SObjectDomain.error('Amount cannot be negative.', record, 'Amount');
            }
        }
    }

    private static Boolean amountChanged(Decimal oldAmount, Decimal newAmount) {
        if (oldAmount == null && newAmount == null) {
            return false;
        }
        if (oldAmount == null || newAmount == null) {
            return true;
        }
        return oldAmount.compareTo(newAmount) != 0;
    }
}
