    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        // Guard against empty or invalid input so we never run a query with an
        // empty IN clause or a non-positive LIMIT.
        if (accountIds == null || accountIds.isEmpty() || maxRecords == null || maxRecords <= 0) {
            return new List<Opportunity>();
        }

        // Reuse the selector's declared field list so the standard fields and
        // field-level security always apply, then append the parent account name.
        List<String> fieldNames = new List<String>();
        for (Schema.SObjectField field : getSObjectFieldList()) {
            fieldNames.add(field.getName());
        }

        String soql = 'SELECT ' + String.join(fieldNames, ', ') + ', Account.Name FROM Opportunity ';
        soql += 'WHERE AccountId IN :accountIds AND IsClosed = false ';
        soql += 'ORDER BY Amount DESC, CloseDate ASC ';
        soql += 'LIMIT :maxRecords';

        return (List<Opportunity>) Database.query(soql);
    }
