public class ContactPhoneCleanup {
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        List<Contact> contacts = [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :contactIds
        ];

        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact contact : contacts) {
            if (String.isNotBlank(contact.Phone)) {
                // Keep only digits and plus signs; strip spaces, dashes, parens, etc.
                contact.Phone = contact.Phone.replaceAll('[^\\d+]', '');
                contactsToUpdate.add(contact);
            }
        }

        Map<Id, String> saveErrors = new Map<Id, String>();

        if (!contactsToUpdate.isEmpty()) {
            for (Database.SaveResult result : Database.update(contactsToUpdate, false)) {
                if (!result.isSuccess() && !result.getErrors().isEmpty()) {
                    saveErrors.put(result.getId(), result.getErrors()[0].getMessage());
                }
            }
        }

        return saveErrors;
    }
}
