/**
 * PipelineSummary
 * Provides aggregated opportunity amounts by stage for a given date range.
 * 
 * Design notes:
 * - Exactly four SOQL queries are issued, one per managed stage. This keeps each
 *   query simple, readable, and guaranteed to produce all four required keys even
 *   when a stage has no matching opportunities.
 * - WITH SECURITY ENFORCED enforces CRUD and field-level security on every query.
 * - Null Amount values are ignored by SUM(); a null aggregate result is normalized
 *   to Decimal.ZERO so the map never contains null values.
 */
public class PipelineSummary {

    private static final List<String> MANAGED_STAGES = new List<String>{
        'Prospecting',
        'Qualification',
        'Proposal/Price Quote',
        'Negotiation/Review'
    };

    private PipelineSummary() {
    }

    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        Map<String, Decimal> totals = new Map<String, Decimal>();

        for (String stage : MANAGED_STAGES) {
            AggregateResult result = [
                SELECT SUM(Amount) totalAmount
                FROM Opportunity
                WHERE StageName = :stage
                  AND CloseDate >= :fromDate
                  AND CloseDate <= :toDate
                WITH SECURITY ENFORCED
            ];

            Decimal stageTotal = (Decimal) result.get('totalAmount');
            totals.put(stage, stageTotal == null ? Decimal.ZERO : stageTotal);
        }

        return totals;
    }
}
