/**
 * DealEventPublisher
 *
 * Publishes one Deal_Stage_Change__e platform event per Opportunity so the data
 * warehouse can react to stage changes.
 *
 * Returns one Database.SaveResult per input opportunity, in the same order as
 * the input list. Because EventBus.publish returns a SaveResult (with
 * isSuccess()/getErrors()) for failed publishes, the caller can inspect each
 * result to know exactly which event failed.
 *
 * Bulk-safe for the <= 200 records passed from the Opportunity trigger handler.
 * A null or empty list publishes nothing and returns an empty list.
 *
 * No deviation: the implementation follows the requested per-opportunity
 * EventBus.publish loop exactly, collecting one SaveResult per input in order.
 */
public class DealEventPublisher {

    /**
     * Publish a stage-change event for every opportunity.
     *
     * @param opportunities up to 200 opportunities from the trigger handler.
     * @return one Database.SaveResult per input opportunity, in input order.
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        List<Database.SaveResult> results = new List<Database.SaveResult>();

        // Empty/null input: publish nothing and return an empty list.
        if (opportunities == null || opportunities.isEmpty()) {
            return results;
        }

        for (Opportunity opp : opportunities) {
            Deal_Stage_Change__e evt = new Deal_Stage_Change__e();
            evt.Opportunity_Id__c = String.valueOf(opp.Id); // 18-character Id
            evt.Stage__c = opp.StageName;
            evt.Amount__c = opp.Amount;

            // Publish individually (not publishAll) so each result is captured
            // in position; a failed publish returns a SaveResult with errors.
            results.add(EventBus.publish(evt));
        }

        return results;
    }
}
