trigger CaseTrigger on Case (after update) {
    /*
     * After a case is saved, survey the customer asynchronously. Each case that
     * just became closed and has a contact is enqueued as its own queueable job.
     * This keeps the trigger fast and isolates failures: if one survey task
     * cannot be created, it does not prevent other cases from being surveyed.
     *
     * Changes:
     * - Detect only the not-closed -> closed transition on Case.IsClosed.
     * - Skip cases without a contact because no task should be created.
     * - Enqueue one CaseSurveyJob per case so bulk close operations handle each
     *   case independently.
     */
    for (Case c : Trigger.new) {
        Case oldCase = Trigger.oldMap.get(c.Id);

        boolean newlyClosed = c.IsClosed && (oldCase == null || !oldCase.IsClosed);
        if (newlyClosed && c.ContactId != null) {
            System.enqueueJob(new CaseSurveyJob(c.Id));
        }
    }
}
