public with sharing class CaseSurveyJob implements Queueable {
    public Id caseId;

    public CaseSurveyJob(Id caseId) {
        this.caseId = caseId;
    }

    public void execute(QueueableContext context) {
        /*
         * Each job handles a single case. The case is re-queried inside the job
         * so we operate on the current state and one job failure does not affect
         * other cases.
         *
         * Changes:
         * - Create the CSAT survey Task asynchronously.
         * - WhatId is the case; WhoId is the case's contact.
         * - Skip cases without a contact.
         */
        Case c = [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id = :caseId
            LIMIT 1
        ];

        if (c == null || c.ContactId == null) {
            return;
        }

        Task survey = new Task(
            WhatId = c.Id,
            WhoId = c.ContactId,
            Subject = 'CSAT survey: ' + c.CaseNumber,
            ActivityDate = Date.today().addDays(2),
            Status = 'Not Started'
        );

        insert survey;
    }
}
