public class RenewalReminderService {

    /**
     * Sends a renewal-reminder email to the owner of each opportunity passed in.
     * Emails are sent one at a time so that a failure on one record does not
     * prevent the remaining emails from being sent.
     *
     * @param opportunityIds IDs of opportunities whose renewals are due
     * @return Number of emails that were sent successfully
     */
    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        Integer emailsSentSuccessfully = 0;

        // Bulk-safe: retrieve all opportunities in a single SOQL query.
        // OwnerId is obtained directly from the Opportunity record to avoid an extra owner query.
        for (Opportunity opp : [SELECT Id, Name, CloseDate, OwnerId
                                FROM Opportunity
                                WHERE Id IN :opportunityIds]) {

            // Defensive: Opportunities always have an owner, but skip if missing.
            if (opp.OwnerId == null) {
                continue;
            }

            Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();
            email.setTargetObjectId(opp.OwnerId);
            email.setSaveAsActivity(false);
            email.setSubject('Renewal due: ' + opp.Name);
            email.setPlainTextBody('The renewal for opportunity "' + opp.Name + '" is due on ' + String.valueOf(opp.CloseDate) + '.');

            try {
                // One call per opportunity keeps the rest of the loop independent
                // if this email fails for any reason.
                Messaging.SendEmailResult result = Messaging.sendEmail(new Messaging.SingleEmailMessage[]{email})[0];
                if (result.isSuccess()) {
                    emailsSentSuccessfully++;
                }
            } catch (Exception e) {
                // Log the individual failure and continue with the next opportunity.
                System.debug('RenewalReminderService: Email send failed for Opportunity ' + opp.Id + ' (Owner ' + opp.OwnerId + '): ' + e.getMessage());
            }
        }

        return emailsSentSuccessfully;
    }
}
