import { LightningElement, wire } from 'lwc';
import { MessageContext, APPLICATION_SCOPE } from 'lightning/MessageContext';

const CHANNEL = 'Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
  @wire(MessageContext) messageContext;

  private subscription;
  private recordId;

  connectedCallback() {
    // Ensure we never hold more than one subscription. If the component is
    // re-inserted without being removed first, drop any existing subscription
    // before creating a new one.
    if (this.subscription) {
      this.messageContext.unsubscribe(this.subscription);
      this.subscription = null;
    }
    this.subscription = this.messageContext.subscribe(
      CHANNEL,
      APPLICATION_SCOPE,
      (message) => this.handleMessage(message)
    );
  }

  disconnectedCallback() {
    // Release the subscription when the component is removed from the page.
    if (this.subscription) {
      this.messageContext.unsubscribe(this.subscription);
      this.subscription = null;
    }
  }

  handleMessage(message) {
    this.recordId = message.recordId;
  }

  handleClear() {
    this.messageContext.publish(CHANNEL, { recordId: null }, APPLICATION_SCOPE);
  }
