import { LightningElement, api } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import { deleteRecord } from 'lightning/uiRecordApi';
import { LightningConfirm } from 'lightning/confirm';

export default class OpportunityActionsTable extends NavigationMixin(LightningElement) {
  @api opportunities;

  get columns() {
    return [
      { fieldName: 'Name', label: 'Name' },
      { fieldName: 'StageName', label: 'Stage' },
      { fieldName: 'Amount', label: 'Amount', type: 'currency' },
      {
        type: 'action',
        label: '',
        typeAttributes: {
          rowActions: [
            { label: 'View', name: 'view' },
            { label: 'Edit', name: 'edit' },
            { label: 'Delete', name: 'delete' }
          ]
        }
      }
    ];
  }

  handleRowAction(event) {
    const { action, row } = event.detail;
    switch (action.name) {
      case 'view':
        this.navigate({
          type: 'standardRecordObject',
          actionName: 'view',
          recordId: row.Id,
          objectApiName: 'Opportunity'
        });
        break;
      case 'edit':
        this.navigate({
          type: 'standardRecordObject',
          actionName: 'edit',
          recordId: row.Id,
          objectApiName: 'Opportunity'
        });
        break;
      case 'delete':
        this.handleDelete(row);
        break;
      default:
        break;
    }
  }

  handleDelete(row) {
    LightningConfirm.open({
      message: 'Are you sure you want to delete this opportunity?',
      label: 'Delete'
    })
      .then((confirmed) => {
        if (confirmed) {
          deleteRecord({ recordId: row.Id })
            .then(() => {
              // Remove the row from the table without mutating the parent's array.
              this.opportunities = this.opportunities.filter((opp) => opp.Id !== row.Id);
              this.showToast('success', 'Opportunity deleted');
            })
            .catch((error) => {
              // Keep the row and report the failure.
              this.showToast('error', 'Delete failed', error.body.message);
            });
        }
        // Cancel: do nothing.
      })
      .catch(() => {
        // Cancelled or dismissed: do nothing.
      });
  }

  showToast(variant, title, message) {
    const event = new CustomEvent('showtoast', {
      bubbles: true,
      composed: true,
      detail: { variant, title, message }
    });
    this.dispatchEvent(event);
  }
}
