import { LightningElement, track } from 'lwc';
import { getQueueStats } from '@salesforce/apex/QueueController.getQueueStats';

const POLL_INTERVAL = 60 * 1000; // 60 seconds

export default class QueueMonitor extends LightningElement {
    @track stats;
    @track error;
    private intervalId;
    private isFetching = false;
    private isVisible = true;

    connectedCallback() {
        // Respect initial visibility: do not request while hidden
        if (document.visibilityState === 'visible') {
            this.loadStats();
            this.startPolling();
        } else {
            this.isVisible = false;
        }

        document.addEventListener('visibilitychange', this.handleVisibilityChange.bind(this));
    }

    disconnectedCallback() {
        this.stopPolling();
        document.removeEventListener('visibilitychange', this.handleVisibilityChange.bind(this));
    }

    handleVisibilityChange() {
        if (document.visibilityState === 'visible') {
            this.isVisible = true;
            this.loadStats();
            this.startPolling();
        } else {
            this.isVisible = false;
            this.stopPolling();
        }
    }

    loadStats() {
        // Never start a request while one is already in flight
        if (this.isFetching) {
            return;
        }

        this.isFetching = true;
        this.error = undefined;

        getQueueStats()
            .then((result) => {
                this.stats = result;
                this.error = undefined;
                this.isFetching = false;
            })
            .catch((error) => {
                this.error = error.body.message;
                this.isFetching = false;
            });
    }

    startPolling() {
        // Ensure only one polling loop at a time
        if (this.intervalId) {
            return;
        }

        this.intervalId = setInterval(() => {
            if (this.isVisible && !this.isFetching) {
                this.loadStats();
            }
        }, POLL_INTERVAL);
    }

    stopPolling() {
        if (this.intervalId) {
            clearInterval(this.intervalId);
            this.intervalId = null;
        }
    }
}
