import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/events';
import { register } from 'force:appDataDefault/RegistrationController/register';

const PERSONAL_EMAIL_DOMAINS = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];

export default class EventRegistrationForm extends LightningElement {
    @track fullName = '';
    @track email = '';
    @track company = '';

    handleFieldChange(event) {
        const input = event.target;
        const field = input.dataset.field;
        const value = event.detail.value ?? '';

        if (field === 'fullName') {
            this.fullName = value;
        } else if (field === 'email') {
            this.email = value;
        } else if (field === 'company') {
            this.company = value;
        }
    }

    handleRegister() {
        const inputs = Array.from(
            this.template.querySelectorAll<HTMLElement>('lightning-input[data-field]')
        ) as HTMLInputElement[];

        const emailInput = inputs.find((input) => input.dataset.field === 'email');
        if (emailInput) {
            const emailDomain = (this.email ?? '').trim().toLowerCase().split('@').pop() ?? '';
            if (PERSONAL_EMAIL_DOMAINS.includes(emailDomain)) {
                emailInput.setCustomValidity('Use your work email address.');
            } else {
                emailInput.setCustomValidity('');
            }
        }

        const validityResults = inputs.map((input) => input.reportValidity());
        if (validityResults.some((isValid) => !isValid)) {
            return;
        }

        register({
            fullName: this.fullName,
            email: this.email,
            company: this.company
        })
            .then(() => {
                this.dispatchEvent(new ShowToastEvent({
                    variant: 'success',
                    title: 'Registered'
                }));
            })
            .catch((error) => {
                const message = error.body?.message ?? error.message ?? 'Registration failed.';
                this.dispatchEvent(new ShowToastEvent({
                    variant: 'error',
                    title: 'Registration failed',
                    message
                }));
            });
    }
}
