import { LightningElement, api, track } from 'lwc';

export default class TaskChecklist extends LightningElement {
    private _heading = '';

    @api heading;

    get heading() {
        return this._heading ? this._heading.toUpperCase() : '';
    }

    set heading(value) {
        this._heading = value;
    }

    @api tasks;

    private _tasks = [];

    get tasks() {
        return this._tasks;
    }

    set tasks(value) {
        this._tasks = value;
        // Work on our own copy: never modify the parent's array or task objects.
        // When the parent passes a new array, replace the list with a copy of it.
        this.items = value ? value.map((task) => ({ ...task })) : [];
        // Keep newly generated ids unique across replacements.
        let max = 0;
        this.items.forEach((task) => {
            if (task.id && typeof task.id === 'string' && task.id.startsWith('new-')) {
                const num = parseInt(task.id.slice(4), 10);
                if (!isNaN(num)) {
                    max = Math.max(max, num);
                }
            }
        });
        this.nextId = max + 1;
    }

    @track items = [];
    @track newLabel = '';
    nextId = 1;

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value ?? '';
    }

    handleAdd() {
        const label = this.newLabel.trim();
        if (!label) {
            return;
        }
        const task = { id: `new-${this.nextId++}`, label, done: false };
        this.items = [...this.items, task];
        this.newLabel = '';
        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        this.items = this.items.map((task) =>
            String(task.id) === id ? { ...task, done: !task.done } : task
        );
    }
}
