/**
 * EmployerService manages current employer affiliations for contacts.
 */
public class EmployerService {

    /**
     * Sets the current employer for each contact in the map.
     * For each contact, ensures there is a Current, primary NPSP affiliation
     * with the given organization, ends any previous primary employer as Former
     * with an end date of today, and relies on NPSP's standard Affiliation
     * trigger to maintain the Contact's primary affiliation lookup.
     *
     * @param employerByContactId Map of Contact Id to Organization Account Id.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = new Set<Id>(employerByContactId.keySet());
        Date today = Date.today();

        // One SOQL query to load all existing affiliations for the affected contacts
        List<npe5__Affiliation__c> affiliations = [
            SELECT Id,
                   npe5__Contact__c,
                   npe5__Organization__c,
                   npe5__Status__c,
                   npe5__Primary__c,
                   npe5__StartDate__c,
                   npe5__EndDate__c,
                   npe5__Role__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :contactIds
        ];

        // Map: contactId + '|' + orgId -> existing affiliation (any status)
        Map<String, npe5__Affiliation__c> affiliationByContactOrg = new Map<String, npe5__Affiliation__c>();
        // Map: contactId -> list of current primary affiliations
        Map<Id, List<npe5__Affiliation__c>> currentPrimariesByContact = new Map<Id, List<npe5__Affiliation__c>>();

        for (npe5__Affiliation__c aff : affiliations) {
            String key = aff.npe5__Contact__c + '|' + aff.npe5__Organization__c;
            if (!affiliationByContactOrg.containsKey(key)) {
                affiliationByContactOrg.put(key, aff);
            }

            if (aff.npe5__Status__c == 'Current' && aff.npe5__Primary__c == true) {
                if (!currentPrimariesByContact.containsKey(aff.npe5__Contact__c)) {
                    currentPrimariesByContact.put(aff.npe5__Contact__c, new List<npe5__Affiliation__c>());
                }
                currentPrimariesByContact.get(aff.npe5__Contact__c).add(aff);
            }
        }

        // Single DML upsert to end previous primary affiliations and create/update new primary affiliations
        List<npe5__Affiliation__c> upsertList = new List<npe5__Affiliation__c>();

        for (Id contactId : employerByContactId.keySet()) {
            Id orgId = employerByContactId.get(contactId);
            if (orgId == null) {
                continue;
            }

            String key = contactId + '|' + orgId;
            npe5__Affiliation__c existingAff = affiliationByContactOrg.get(key);

            // If this organization is already the current primary affiliation, do nothing
            if (existingAff != null && existingAff.npe5__Status__c == 'Current' && existingAff.npe5__Primary__c == true) {
                continue;
            }

            // End all current primary affiliations for this contact.
            // None will be the new org because we skipped above when it was already primary.
            List<npe5__Affiliation__c> currentPrimaries = currentPrimariesByContact.get(contactId);
            if (currentPrimaries != null) {
                for (npe5__Affiliation__c cp : currentPrimaries) {
                    cp.npe5__Status__c = 'Former';
                    cp.npe5__EndDate__c = today;
                    cp.npe5__Primary__c = false;
                    upsertList.add(cp);
                }
            }

            // Prepare (or update) the new primary affiliation
            npe5__Affiliation__c newAff = new npe5__Affiliation__c();
            newAff.npe5__Contact__c = contactId;
            newAff.npe5__Organization__c = orgId;
            newAff.npe5__Status__c = 'Current';
            newAff.npe5__Primary__c = true;
            newAff.npe5__EndDate__c = null; // clear any end date

            if (existingAff != null) {
                // Update the existing record; do not overwrite StartDate
                newAff.Id = existingAff.Id;
            } else {
                // New affiliation: set start date to today
                newAff.npe5__StartDate__c = today;
            }

            upsertList.add(newAff);
        }

        // One DML statement: upsert handles updates to existing records and inserts for new ones.
        // NPSP's standard Affiliation trigger will maintain the Contact's primary affiliation lookup
        // and ensure the previous primary affiliation is properly ended.
        if (!upsertList.isEmpty()) {
            Database.upsert(upsertList);
        }
    }
}
