/**
 * Service for managing NPSP GAU Allocations on opportunities.
 *
 * Allocations are stored as percentages. The dollar amount is derived by NPSP from
 * the percentage and the opportunity amount, so the allocation amounts stay correct
 * automatically when the opportunity amount is later corrected (no further code is
 * required from this service).
 */
public class GauAllocationService {

    public class AllocationException extends Exception {}

    /**
     * Replace all GAU allocations of the opportunity with one allocation per entry in
     * percentByGauId. Percentages are expressed as whole numbers (e.g. 60 means 60%).
     * The combined total may be below 100%; the remainder stays unallocated.
     */
    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId,
                                                              Map<Id, Decimal> percentByGauId) {
        // --- Validate the input map ---------------------------------------------
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('A non-empty map of GAU Ids to percentages is required.');
        }

        // --- Validate each percentage -------------------------------------------
        Decimal totalPercent = 0;
        for (Id gauId : percentByGauId.keySet()) {
            Decimal percent = percentByGauId.get(gauId);
            if (percent == null || percent <= 0) {
                throw new AllocationException('Every GAU allocation percentage must be provided and greater than 0.');
            }
            totalPercent += percent;
        }

        // --- Validate the combined total ----------------------------------------
        if (totalPercent > 100) {
            throw new AllocationException('The combined GAU allocation percentage cannot exceed 100%.');
        }

        // --- Validate that every GAU exists and is active ------------------------
        Map<Id, npsp__General_Accounting_Unit__c> gauById = new Map<Id, npsp__General_Accounting_Unit__c>(
            [SELECT Id, npsp__Active__c
             FROM npsp__General_Accounting_Unit__c
             WHERE Id IN :percentByGauId.keySet()]
        );

        for (Id gauId : percentByGauId.keySet()) {
            npsp__General_Accounting_Unit__c gau = gauById.get(gauId);
            if (gau == null || !gau.npsp__Active__c) {
                throw new AllocationException('The GAU ' + gauId + ' does not exist or is inactive.');
            }
        }

        // --- Replace existing allocations ----------------------------------------
        // All validation passed, so it is now safe to modify data.
        delete [SELECT Id
                FROM npsp__Allocation__c
                WHERE npsp__Opportunity__c = :opportunityId];

        // --- Build the new allocations -------------------------------------------
        // Store the percentage only. The Amount field is maintained by NPSP from the
        // percentage and the opportunity amount, so it is recalculated automatically
        // whenever the opportunity amount is corrected.
        List<npsp__Allocation__c> allocations = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            npsp__Allocation__c allocation = new npsp__Allocation__c();
            allocation.npsp__Opportunity__c = opportunityId;
            allocation.npsp__General_Accounting_Unit__c = gauId;
            allocation.npsp__Percent__c = percentByGauId.get(gauId);
            allocations.add(allocation);
        }

        insert allocations;

        return allocations;
    }
}
