public with sharing class HouseholdService {
    private static Id householdRecordTypeId;

    static {
        // Resolve the Household Account record type by DeveloperName so we never
        // hard-code a record type Id.
        List<Schema.RecordType> recordTypes = [
            SELECT Id
            FROM Schema.RecordType
            WHERE SObjectType = 'Account'
              AND DeveloperName = 'HH_Account'
            LIMIT 1
        ];
        householdRecordTypeId = recordTypes.isEmpty() ? null : recordTypes[0].Id;
    }

    public static Id createHousehold(List<Contact> members) {
        // Guard clause: members must be provided.
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members cannot be null or empty');
        }

        if (householdRecordTypeId == null) {
            throw new IllegalArgumentException(
                'The Household Account record type (HH_Account) could not be found.'
            );
        }

        // Insert the brand-new contacts first so we can reference their Ids.
        List<Contact> contacts = new List<Contact>(members);
        insert contacts;

        // Create the NPSP household account.
        // - RecordTypeId = HH_Account makes this a real NPSP household.
        // - Name is intentionally left unset so NPSP generates the household name.
        // - npe01__One2OneContact__c designates the first contact as primary.
        Account household = new Account(
            RecordTypeId = householdRecordTypeId,
            npe01__One2OneContact__c = contacts[0].Id
        );
        insert household;

        // Link every contact to the single new household.
        for (Contact c : contacts) {
            c.AccountId = household.Id;
        }
        update contacts;

        return household.Id;
    }
}
