/**
 * Service that converts an NPSP opportunity pledge into a recurring monthly
 * installment plan by replacing the pledge's open payments.
 */
public class PaymentPlanService {

    /**
     * Thrown when a payment plan cannot be scheduled. The exception is thrown
     * before any DML is executed, so the database is left untouched.
     */
    public class PaymentPlanException extends Exception {}

    // Opportunity stages that are considered closed and therefore not editable.
    private static final Set<String> CLOSED_STAGE_NAMES = new Set<String> {
        'Closed Won',
        'Closed Lost'
    };

    /**
     * Replaces the opportunity's unpaid, not-written-off payments with a new
     * monthly installment plan.
     *
     * @param opportunityId      The NPSP opportunity (pledge) to re-schedule.
     * @param numberOfPayments   Number of installments to create (must be >= 1).
     * @param firstPaymentDate   Date of the first installment.
     * @return                   The newly inserted payments, in schedule order.
     */
    public static List<npe01__OppPayment__c> scheduleInstallments(
            Id opportunityId,
            Integer numberOfPayments,
            Date firstPaymentDate
    ) {
        // ---- Validate before any write -------------------------------------
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException(
                    'numberOfPayments must be provided and greater than 0.');
        }
        if (firstPaymentDate == null) {
            throw new PaymentPlanException('firstPaymentDate is required.');
        }

        // ---- Read opportunity and its payments (no writes yet) -------------
        List<npe01__Opportunity__c> opportunities = [
            SELECT Amount, StageName,
                   (SELECT Id, npe01__Payment_Amount__c, npe01__Scheduled_Date__c,
                        npe01__Payment_Date__c, npe01__Paid__c,
                        npe01__Written_Off__c, npe01__Payment_Method__c
                    FROM npe01__OppPayment__r)
            FROM npe01__Opportunity__c
            WHERE Id = :opportunityId
            LIMIT 1
        ];

        if (opportunities.isEmpty()) {
            throw new PaymentPlanException('Opportunity not found: ' + opportunityId);
        }

        npe01__Opportunity__c opp = opportunities[0];
        List<npe01__OppPayment__c> payments = opp.npe01__OppPayment__r;

        // Closed opportunities cannot be re-scheduled.
        if (opp.StageName != null
                && ('Closed Won'.equalsIgnoreCase(opp.StageName)
                    || 'Closed Lost'.equalsIgnoreCase(opp.StageName))) {
            throw new PaymentPlanException(
                    'Cannot schedule installments on a closed opportunity.');
        }

        // ---- Compute outstanding amount ------------------------------------
        // Outstanding = Amount - (amounts of paid payments) - (amounts of
        // written-off payments).
        Decimal paidAmount = Decimal.valueOf(0);
        Decimal writtenOffAmount = Decimal.valueOf(0);
        for (npe01__OppPayment__c p : payments) {
            Decimal amount = p.npe01__Payment_Amount__c == null
                    ? Decimal.valueOf(0)
                    : p.npe01__Payment_Amount__c;
            if (p.npe01__Paid__c == true) {
                paidAmount += amount;
            }
            if (p.npe01__Written_Off__c == true) {
                writtenOffAmount += amount;
            }
        }
        Decimal outstanding = opp.Amount == null
                ? Decimal.valueOf(0)
                : opp.Amount - paidAmount - writtenOffAmount;

        if (outstanding == null || outstanding.signum() <= 0) {
            throw new PaymentPlanException(
                    'Outstanding amount must be greater than zero.');
        }

        // ---- Compute instalment amounts in cents ---------------------------
        // Working in cents avoids decimal division rounding errors. Every
        // instalment except the last is the outstanding amount divided by the
        // number of payments, rounded down to the cent; the last instalment
        // absorbs the remainder so the total equals the outstanding amount.
        Integer totalCents = (outstanding * 100).setScale(0, RoundingMode.DOWN).intValue();
        Integer baseCents = totalCents / numberOfPayments; // floor for positive values
        Integer lastCents = totalCents - (baseCents * (numberOfPayments - 1));

        // ---- Delete current unpaid, not-written-off payments ---------------
        List<npe01__OppPayment__c> toDelete = new List<npe01__OppPayment__c>();
        for (npe01__OppPayment__c p : payments) {
            boolean unpaid = (p.npe01__Paid__c == null || !p.npe01__Paid__c);
            boolean notWrittenOff = (p.npe01__Written_Off__c == null || !p.npe01__Written_Off__c);
            if (unpaid && notWrittenOff) {
                toDelete.add(p);
            }
        }
        if (!toDelete.isEmpty()) {
            delete toDelete;
        }

        // ---- Create new unpaid instalment payments in schedule order -------
        List<npe01__OppPayment__c> result = new List<npe01__OppPayment__c>();
        for (Integer i = 0; i < numberOfPayments; i++) {
            npe01__OppPayment__c p = new npe01__OppPayment__c();
            p.npe01__Opportunity__c = opportunityId;
            p.npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i);
            p.npe01__Payment_Amount__c = (i == numberOfPayments - 1)
                    ? new Decimal(lastCents, 2)
                    : new Decimal(baseCents, 2);
            p.npe01__Paid__c = false;
            p.npe01__Written_Off__c = false;
            p.npe01__Payment_Date__c = null;
            p.npe01__Payment_Method__c = null;
            result.add(p);
        }

        insert result;
        return result;
    }
}
