public with sharing class FamilyService {

    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        // Null or empty input does nothing
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Collect all unique contact IDs involved in the input pairs
        Set<Id> allContactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            if (childId == null) continue;
            allContactIds.add(childId);
            Id parentId = parentIdByChildId.get(childId);
            if (parentId != null) {
                allContactIds.add(parentId);
            }
        }

        if (allContactIds.isEmpty()) {
            return;
        }

        // Single SOQL query to find any existing relationships between the involved contacts
        // in either direction, so we can skip pairs that are already linked.
        List<npe4__Relationship__c> existingRels = [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :allContactIds
            AND npe4__RelatedContact__c IN :allContactIds
        ];

        // Build a set of existing contact pairs (both directions) for O(1) lookup
        Set<String> existingPairs = new Set<String>();
        for (npe4__Relationship__c rel : existingRels) {
            existingPairs.add(rel.npe4__Contact__c + '|' + rel.npe4__RelatedContact__c);
        }

        // Prepare new relationship records, skipping any pair that already exists
        // in either direction so the import is re-runnable.
        List<npe4__Relationship__c> newRels = new List<npe4__Relationship__c>();
        for (Id childId : parentIdByChildId.keySet()) {
            if (childId == null) continue;
            Id parentId = parentIdByChildId.get(childId);
            if (parentId == null || childId == parentId) continue;

            String pairForward = childId + '|' + parentId;
            String pairReverse = parentId + '|' + childId;

            if (existingPairs.contains(pairForward) || existingPairs.contains(pairReverse)) {
                continue;
            }

            newRels.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = 'Parent',
                npe4__Status__c = 'Current',
                npe4__ReciprocalRelationship__c = false
            ));
        }

        // Single DML statement to insert all new relationships.
        // With ReciprocalRelationship = false, NPSP's trigger automatically
        // creates the reciprocal record on the parent's side. The reciprocal
        // Type is resolved by the Relationship Lookup (Son/Daughter/Child)
        // based on the child's gender, so viewing the parent's relationships
        // shows the child correctly without needing a second insert.
        if (!newRels.isEmpty()) {
            insert newRels;
        }
    }
}
