public with sharing class RecordAccessService {

    /**
     * Returns the subset of the given record IDs that the running user can edit,
     * as determined by the UserRecordAccess object.
     *
     * @param recordIds IDs of records to check (may span multiple objects).
     * @return The IDs the user can edit. Never null.
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        if (recordIds == null || recordIds.isEmpty()) {
            return new Set<Id>();
        }

        Set<Id> editableIds = new Set<Id>();
        List<Id> ids = new List<Id>(recordIds);

        // UserRecordAccess supports at most 100 RecordId filters per query.
        // Chunk the input so that up to 2,000 IDs use no more than 20 SOQL queries.
        Integer batchSize = 100;
        for (Integer i = 0; i < ids.size(); i += batchSize) {
            List<Id> batch = ids.subList(i, Math.min(i + batchSize, ids.size()));

            for (UserRecordAccess access : [
                SELECT
                    HasEditAccess,
                    RecordId
                FROM UserRecordAccess
                WHERE RecordId IN :batch
                AND UserId = :UserInfo.getUserId()
            ]) {
                if (access.HasEditAccess) {
                    editableIds.add(access.RecordId);
                }
            }
        }

        return editableIds;
    }
}
