public class AccountOwnershipService {

    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        // Bypass ALL Account trigger actions for the remainder of the transaction.
        // This satisfies the requirement that no Account automation runs for this change.
        TriggerBase.bypass(Account.SObjectType);

        try {
            // 1 SOQL: Load accounts together with their contacts in a single query.
            List<Account> accounts = [
                SELECT Id, (SELECT Id FROM Contacts)
                FROM Account
                WHERE Id IN :accountIds
            ];

            // 1 DML: Update account owners. Account triggers remain bypassed.
            for (Account acc : accounts) {
                acc.OwnerId = newOwnerId;
            }
            update accounts;

            // Collect the already-queried contacts to update their owners.
            List<Contact> contactsToUpdate = new List<Contact>();
            for (Account acc : accounts) {
                for (Contact con : acc.Contacts) {
                    con.OwnerId = newOwnerId;
                    contactsToUpdate.add(con);
                }
            }

            // 1 DML: Update contact owners. Contact triggers run normally.
            if (!contactsToUpdate.isEmpty()) {
                update contactsToUpdate;
            }
        } finally {
            // Restore Account automation regardless of success or failure so that
            // the rest of the transaction behaves normally.
            TriggerBase.clearBypass(Account.SObjectType);
        }
    }
}
