public with sharing class TA_Opportunity_CollectForErpSync 
    implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {

    /**
     * Static collection of Opportunity Ids that need to be synchronized to the ERP.
     * The collection persists across trigger invocations within the same DML operation
     * (e.g. across the 200 + 50 chunks of a single 250-record insert) and is cleared
     * by OpportunityErpSyncFinalizer at the end of each DML operation so the next
     * operation starts with a clean slate.
     */
    private static Set<Id> idsToSync = new Set<Id>();

    public void afterInsert(List<SObject> triggerNew) {
        if (triggerNew == null) {
            return;
        }
        for (SObject opp : triggerNew) {
            if (opp != null && opp.Id != null) {
                idsToSync.add(opp.Id);
            }
        }
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        if (triggerNew == null || triggerOld == null) {
            return;
        }
        for (Integer i = 0; i < triggerNew.size(); i++) {
            SObject opp = triggerNew[i];
            SObject oldOpp = triggerOld[i];
            if (opp == null || oldOpp == null || opp.Id == null) {
                continue;
            }
            // Only sync when StageName actually changed.
            if (!String.valueOf(opp.get('StageName')).equals(String.valueOf(oldOpp.get('StageName')))) {
                idsToSync.add(opp.Id);
            }
        }
    }

    public static Set<Id> getIdsToSync() {
        return idsToSync;
    }

    public static void clearIdsToSync() {
        idsToSync.clear();
    }
}
