@IsTest
public class TA_Opportunity_GuardAmountDecreaseTest {

    @IsTest
    private static void testReductionMoreThanHalfIsRejectedWithOneError() {
        TA_Opportunity_GuardAmountDecrease action = new TA_Opportunity_GuardAmountDecrease();

        Opportunity oldOpp = new Opportunity();
        oldOpp.Id = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        oldOpp.Amount = 1000;

        Opportunity newOpp = new Opportunity();
        newOpp.Id = oldOpp.Id;
        newOpp.Amount = 499;

        List<Opportunity> triggerOld = new List<Opportunity> { oldOpp };
        List<Opportunity> triggerNew = new List<Opportunity> { newOpp };

        action.beforeUpdate(triggerNew, triggerOld);

        System.assertTrue(newOpp.hasErrors(), 'Expected the record to have errors');
        System.assertEquals(1, newOpp.getErrors().size(), 'Expected exactly one error');
        System.assertEquals(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            newOpp.getErrors()[0].getMessage(),
            'Error message must match ERROR_MESSAGE'
        );
    }

    @IsTest
    private static void testReductionExactlyHalfIsAccepted() {
        TA_Opportunity_GuardAmountDecrease action = new TA_Opportunity_GuardAmountDecrease();

        Opportunity oldOpp = new Opportunity();
        oldOpp.Id = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        oldOpp.Amount = 1000;

        Opportunity newOpp = new Opportunity();
        newOpp.Id = oldOpp.Id;
        newOpp.Amount = 500;

        action.beforeUpdate(
            new List<Opportunity> { newOpp },
            new List<Opportunity> { oldOpp }
        );

        System.assertFalse(newOpp.hasErrors(), 'Expected no errors for an exact half reduction');
        System.assertEquals(0, newOpp.getErrors().size(), 'Expected no errors');
