/*
 * Trigger Action: TA_Lead_NormalizeContactInfo
 *
 * Cleans Lead contact information before insert so web-to-lead submissions
 * and list imports save with clean data:
 *
 * - Email: leading/trailing whitespace removed and lower-cased (null stays null)
 * - Company: leading/trailing whitespace removed (null stays null)
 * - LeadSource: defaults to 'Web' when blank; an existing value is kept
 *
 * Runs in before insert, so the cleaned values are persisted with the record
 * itself: no extra DML and no SOQL. Bulk-safe: one loop handles 200 leads
 * in a single insert.
 */
public inherited sharing class TA_Lead_NormalizeContactInfo implements TriggerAction.BeforeInsert {

    public void beforeInsert(List<SObject> triggerNew) {
        for (Lead lead : (List<Lead>) triggerNew) {
            // Email: trim and lower-case; null stays null
            if (lead.Email != null) {
                lead.Email = lead.Email.trim().toLowerCase();
            }

            // Company: trim whitespace; null stays null
            if (lead.Company != null) {
                lead.Company = lead.Company.trim();
            }

            // LeadSource: default to 'Web' when blank; keep existing value
            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = 'Web';
            }
        }
    }
}
