/**
 * TA_Contact_Queries
 *
 * Singleton holder for the parent Accounts of the Contacts being inserted in
 * the current trigger execution.
 *
 * The inner Service class is a Trigger Actions Framework action that populates
 * accountsById with a single SOQL query (Order 1, runs first). The other
 * before insert actions read the parent Account from this shared map, so the
 * org issues exactly one Account query per trigger execution and no action
 * queries Accounts itself.
 */
public class TA_Contact_Queries {

    private static TA_Contact_Queries instance;

    private TA_Contact_Queries() {
        accountsById = new Map<Id, Account>();
    }

    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    public Map<Id, Account> accountsById;

    /**
     * Trigger action that loads the parent accounts into the shared map.
     * Reloads the map on every before insert execution so the map always
     * reflects the current transaction, even when later DML involves other
     * accounts.
     */
    public class Service extends MetadataTriggerHandler {
        public void beforeInsert(List<SObject> triggerNew) {
            Set<Id> accountIds = new Set<Id>();
            for (SObject s : triggerNew) {
                Contact c = (Contact) s;
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }

            if (accountIds.isEmpty()) {
                accountsById = new Map<Id, Account>();
            } else {
                accountsById = new Map<Id, Account>([
                    SELECT Id,
                           BillingStreet,
                           BillingCity,
                           BillingPostalCode,
                           BillingCountry,
                           AccountSource
                    FROM Account
                    WHERE Id IN :accountIds
                ]);
            }
        }
    }
}
