/**
 * TA_Contact_DefaultLeadSource
 *
 * Trigger action (before insert, Order 20). When a new Contact has a parent
 * Account and a blank LeadSource, defaults it to the Account's AccountSource.
 * Contacts without an Account, or with a LeadSource already set, are left
 * alone.
 *
 * The parent Account is read from the shared map populated by
 * TA_Contact_Queries.Service, so this action issues no queries itself.
 */
public class TA_Contact_DefaultLeadSource extends MetadataTriggerHandler {
    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accounts = TA_Contact_Queries.getInstance().accountsById;
        for (SObject s : triggerNew) {
            Contact c = (Contact) s;

            if (c.AccountId == null) {
                continue;
            }
            if (c.LeadSource != null) {
                continue;
            }
            Account acc = accounts.get(c.AccountId);
            if (acc == null) {
                continue;
            }

            c.LeadSource = acc.AccountSource;
        }
    }
}
